const repositories = ["fragments/web", "fragments/api", "fragments/docs"];

<Combobox loading placeholder="Search repositories…" defaultOpen>
  <Combobox.Input aria-label="Repository" />
  <Combobox.Content>
    {repositories.map((repo) => (
      <Combobox.Item key={repo} value={repo}>
        {repo}
      </Combobox.Item>
    ))}
  </Combobox.Content>
</Combobox>
